		rules.add(rule().condition(all(allTypes("attribute", "multiple", "integer"), trigger("getter"))).output(literal("public java.util.List<Integer> ")).output(placeholder("name", "firstLowerCase")).output(literal("() {\n\tString value = current$().text(")).output(expression().output(placeholder("isStruct", "prefix")).output(literal(" "))).output(literal("\"")).output(placeholder("name")).output(literal("\");\n\treturn value == null ? java.util.Collections.emptyList() : java.util.Arrays.stream(value.split(\"\\0\")).map(v -> Integer.parseInt(v)).toList();\n}")));
