		rules.add(rule().condition(all(allTypes("attribute", "subject"), trigger("getter"))).output(literal("public ")).output(placeholder("targetType", "FirstUpperCase")).output(literal(" ")).output(placeholder("name", "firstLowerCase")).output(literal("() {\n\treturn new ")).output(placeholder("targetType", "FirstUpperCase")).output(literal("(datamart$().getSubject(current$().text(")).output(expression().output(placeholder("isStruct", "prefix")).output(literal(" "))).output(literal("\"")).output(placeholder("name")).output(literal("\"), \"")).output(placeholder("targetType")).output(literal("\"), datamart());\n}")));
		rules.add(rule().condition(all(allTypes("attribute", "text"), trigger("getter"))).output(literal("public ")).output(placeholder("type")).output(literal(" ")).output(placeholder("name", "firstLowerCase")).output(literal("() {\n\treturn current$().text(")).output(expression().output(placeholder("isStruct", "prefix")).output(literal(" "))).output(literal("\"")).output(placeholder("name")).output(literal("\");\n}")));
		rules.add(rule().condition(all(allTypes("attribute", "word"), trigger("getter"))).output(literal("public ")).output(placeholder("name", "FirstUpperCase")).output(literal(" ")).output(placeholder("name", "firstLowerCase")).output(literal("() {\n\tString value = current$().text(")).output(expression().output(placeholder("isStruct", "prefix")).output(literal(" "))).output(literal("\"")).output(placeholder("name")).output(literal("\");\n\treturn value == null ? null : ")).output(placeholder("name", "FirstUpperCase")).output(literal(".valueOf(value);\n}")));
		rules.add(rule().condition(all(all(allTypes("attribute"), allTypes("real")), trigger("getter"))).output(literal("public Double ")).output(placeholder("name", "firstLowerCase")).output(literal("() {\n\treturn current$().number(")).output(expression().output(placeholder("isStruct", "prefix")).output(literal(" "))).output(literal("\"")).output(placeholder("name")).output(literal("\").doubleValue();\n}")));
