		rules.add(rule().condition(all(all(allTypes("attribute"), allTypes("boolean")), trigger("getter"))).output(literal("public Boolean ")).output(placeholder("name", "firstLowerCase")).output(literal("() {\n\treturn current$().number(\"")).output(placeholder("name")).output(literal(").intValue != 0;\n}")));
		rules.add(rule().condition(all(all(allTypes("attribute"), allTypes("date")), trigger("getter"))).output(literal("public java.util.Date ")).output(placeholder("name", "firstLowerCase")).output(literal("() {\n\treturn new java.util.Date(current$().number(")).output(expression().output(placeholder("isStruct", "prefix")).output(literal(" "))).output(literal("\"")).output(placeholder("name")).output(literal("\").longValue());\n}")));
